26	struct DialogFacts
27	{
28	    std::string title;
29	    std::string text;
30	    bool        ok{false}, yes{false}, no{false}, cancel{false};
31	    // Orca's STEP import settings, recognised by type: its Cancel abandons
32	    // the whole load, so it is the one dialog whose least change is OK.
33	    bool        step_import{false};
34	};
35	
36	DialogFacts read_dialog(wxWindow& dialog);
37	
38	// The choice that changes least, from the buttons alone: No, else Cancel,
39	// else OK, else Yes (Orca offers a lone Yes only where it acts regardless).
40	// A dialog with none of them is cancelled and marked unrecognised.
41	OrcaMessage least_change_answer(const DialogFacts& facts, int& answer);
42	
43	class ScopedDialogListener
44	{
45	public:
46	    // Returns the id ShowModal would have returned, or nothing to pass.
47	    using Listener = std::function<std::optional<int>(wxWindow& dialog, const DialogFacts& facts)>;
48	
49	    explicit ScopedDialogListener(Listener listener);
50	    ~ScopedDialogListener();
51	    ScopedDialogListener(const ScopedDialogListener&)            = delete;
52	    ScopedDialogListener& operator=(const ScopedDialogListener&) = delete;
53	
54	private:
55	    friend bool dispatch_dialog(wxWindow& dialog, int& answer);
56	    Listener              m_listener;
57	    ScopedDialogListener* m_outer{nullptr};
58	};
