60	// Answers every dialog with the least change and writes each one down: the
61	// file load's listener, and the safety net around a tool's Orca calls.
62	class ScopedLeastChangeAnswers
63	{
64	public:
65	    explicit ScopedLeastChangeAnswers(bool prefer_cancel = false);
66	    const std::vector<OrcaMessage>& messages() const { return m_messages; }
67	    std::vector<OrcaMessage>        take_messages() { return std::move(m_messages); }
68	    void                            add_message(OrcaMessage message) { m_messages.push_back(std::move(message)); }
69	
70	private:
71	    std::vector<OrcaMessage> m_messages;
72	    ScopedDialogListener     m_listener; // after m_messages, which it writes to
